    for (const initial of [undefined, serialize([pref('density', 'wide')])]) {
      const directory = await fixture(initial);
      run(directory, 'set', token);
      if (initial === undefined) await assert.rejects(stat(directory), { code: 'ENOENT' });
      else assert.deepEqual(await readFile(logPath(directory)), Buffer.from(initial));
    }
